import {Config, Field} from 'alinea'
import {createCMS} from 'alinea/server'

export const Page = Config.document('Page', {
  fields: {
    body: Field.text('Body', {multiline: true})
  }
})

export const cms = createCMS({
  schema: {Page},
  workspaces: {
    main: Config.workspace('Example', {
      source: 'content',
      mediaDir: 'public/media',
      roots: {
        pages: Config.root('Pages', {contains: ['Page']}),
        media: Config.media()
      }
    })
  },
  baseUrl: {
    development: 'http://localhost:3000',
    production: 'https://example.com'
  },
  handlerUrl: '/api/cms',
  adminPath: '/admin',
  preview: true
})

import {cms, Page} from '~~/cms'

export default defineEventHandler(async event => {
  const {url} = getQuery(event)
  const page = await cms.first({
    type: Page,
    url: String(url),
    select: {title: Page.title, body: Page.body}
  })
  if (!page) throw createError({statusCode: 404, statusMessage: 'Not found'})
  return page
})

